body.usercss:

.topFixBanner {
    text-align: left;
    background-color: #ffffff;
    padding: 20px 0px 20px 20px;
    width: 100%;
    border-bottom: #666666 solid 2px;
}

.topFixBannerFixed {
    position: fixed;
    top: 0px;
    text-align: left;
    padding-left: 20px;
}

.category_selected {
    background-color: #50b747;
}

#CATEGORY {
    background-color: white;
    color: #404040;
    cursor: context-menu;
}

userscript.function:

const activTabId = Sepoa.request.alias;

doQuery(activTabId, selectedCategory);
gridColumnInit(callFunction('p', 'getActiveTabId', []));


var maxRowId = (gridObj.getRowsNum() + 1)
gridObj.addRow(maxRowId, '', 0);
//gridObj.cells(maxRowId, gridObj.getColIndexById('ITEM_SEQ' )).setValue(maxRowId);
gridObj.cells(maxRowId, gridObj.getColIndexById('SELECTED')).setValue("1");
gridObj.cells(maxRowId, gridObj.getColIndexById('CATEGORY')).setValue(selectedCategory);
gridObj.cells(maxRowId, gridObj.getColIndexById('ITEM_NO')).setValue(getDocumentNumber('CI'));


            if (gridObj.getSelectedRows('SELECTED').length == 0) {
                Alert(Sepoa.cache.text.get('MESSAGE.1004'));
                return;
            }

            if (gridObj.getGridChangedRows("SELECTED").length > 0 && Confirm(Sepoa.cache.text.get('MESSAGE.1015'), function(result) {
				if (result) {
					gridObj.editStop();
					gridObj.postTransaction(window.CONTEXT_NAME + '/SepoaGrid.sux', ['mode=doSave', 'PROCESS_ID=sepoa.svc.contract.SepoaContractItem', 'METHOD=doDelete'], 'SELECTED');
				}
			}));


dataOutput.setValue('CONT_TYPE', contType);
dataOutput.setValue('CATEGORY', category);
var processID = 'sepoa.svc.contract.SepoaContractItem';
var methodID = 'doQuery';
var grid = gridObj;

var params = [];
params.push('mode=doQuery');
params.push('PROCESS_ID=' + processID);
params.push('METHOD=' + methodID);

grid.postConnection(window.CONTEXT_NAME + '/SepoaGrid.sux', params);
grid.clearAll(false);


            for(let target of categoryIds) {
                btnObj._objPulls[target]._area.base.classList.remove('category_selected');
            }
            btnObj._objPulls[selectedCategory]._area.base.classList.add('category_selected');

            var msg = obj.getUserData("", "message");
            var status = obj.getUserData("", "status");
            if (status != "true") {
                Alert(msg);
                return;
            }else {
            	for (var i = 0; i < gridObj.getRowsNum(); i++) {
            		let item_code = gridObj.cells2(i, gridObj.getColIndexById('ITEM_CODE')).getValue();
	                if(item_code == "U" || item_code =="C" || item_code=="E"){
	                	gridObj.cells2(i, gridObj.getColIndexById('ATTACH')).setDisabled(true);
	                	gridObj.cells2(i, gridObj.getColIndexById('PREVIEW_ATTACH')).setDisabled(true);
	                	gridObj.cells2(i, gridObj.getColIndexById('DISPLAY_TEMPLATE')).setDisabled(true);
	                	gridObj.cells2(i, gridObj.getColIndexById('DISPLAY_EDIT')).setDisabled(true);
	                }else { 
		                if (gridObj.cells2(i, gridObj.getColIndexById('ATTACH_FLAG')).getValue() == 'Y') {
		                    gridObj.cells2(i, gridObj.getColIndexById('ATTACH')).setIcon('ATTACH_IMG2');
		                    gridObj.cells2(i, gridObj.getColIndexById('ATTACH')).cell.children[0].style = 'filter:none';
		                }else if (gridObj.cells2(i, gridObj.getColIndexById('PRE_ATTACH_FLAG')).getValue() == 'Y') {
		                    gridObj.cells2(i, gridObj.getColIndexById('PREVIEW_ATTACH')).setIcon('ATTACH_IMG2');
		                    gridObj.cells2(i, gridObj.getColIndexById('PREVIEW_ATTACH')).cell.children[0].style = 'filter:none';
		                }
	                }
	            }
            }


        	var selectedRows = gridObj.getSelectedRows('SELECTED');
            if (selectedRows.length == 0) {
                Alert(Sepoa.cache.text.get('MESSAGE.1004'));
                return;
            }

            if (!gridObj.validate('SELECTED')) {
                Alert(Sepoa.cache.text.get('MESSAGE.0003'));
                return;
            }

            for(let rowId of selectedRows) {
            	var desFilePath = gridObj.cells(rowId, gridObj.getColIndexById('DES_FILE_PATH')).getValue();
            	var itemCode = gridObj.cells(rowId, gridObj.getColIndexById('ITEM_CODE')).getValue();
            	var itemType = gridObj.cells(rowId, gridObj.getColIndexById('ITEM_TYPE')).getValue();
				if(itemType == 'IMAGE' && desFilePath == '') {
					Alert(Sepoa.cache.text.get('POA_CONTRACT.MESSAGE_0035').replace('#ITEM_CODE#', itemCode));		//이미지 항목에 파일첨부가 필요합니다.<br>항목 데이터코드 : ${ITEM_CODE}
					return;
				}
            }

            var activTabId = callFunction('CT_108', 'getActiveTabId', []);
            Confirm(Sepoa.cache.text.get('MESSAGE.1018'), function(result) {
                if (result) {
                    dataOutput.setValue("CATEGORY", selectedCategory);
                    gridObj.editStop();
                    gridObj.postTransaction(window.CONTEXT_NAME + '/SepoaGrid.sux', ['mode=doSave', 'PROCESS_ID=sepoa.svc.contract.SepoaContractItem', 'METHOD=doSave'], 'SELECTED');
                    //doQuery(activTabId, selectedCategory);
                }
            });


var mode = obj.mode;
var status = obj.status;
var message = obj.message;
var activTabId = Sepoa.request.alias;
if (status == "true") {
    Alert(message);
    doQuery(activTabId, selectedCategory);
} else {
    Alert(message);
}


//최초에 계약서(COMMON)이 일단 선택되어 보이도록 css
const alias = Sepoa.request.alias;
if(alias == 'B') {
    btnObj.showButton('SEAL', 'TEMPLATE', false);
} else if(alias == 'S') {
    btnObj.showButton('SIGNER,COMMON', false);
}


var activTabId = callFunction('CT_108', 'getActiveTabId', []);

switch (id) {
    case 'ADD':
        addRow();
        break;
    case 'SAVE':
        doSave();
        break;
    case 'DELETE':
        doDelete();
        break;
    case 'COMMON':
    case 'SIGNER':
    case 'SEAL':
    case 'ATTACH_DOC':
        selectedCategory = id;
        doQuery(activTabId, selectedCategory);
        break;
}


// 사용안함

var m = gridObj.getRowsNum();

for (var i = 0; i < m; i++) {
    gridObj.cells(gridObj.getRowId(i), gridObj.getColIndexById('ITEM_SEQ')).setValue(i + 1);
}

gridObj.sortRows(gridObj.getColIndexById('ITEM_SEQ'));
gridObj.allRowsChecked('SELECTED', true);


            //return selectedCategory
            let isCategory = null;

            btnObj.forEachBtn((data) => {
			    if(btnObj._objPulls[data]._area.base.classList.contains('category_selected')) {
			        isCategory = data;
			    }
			});

            return isCategory;


var isHidden = false;
var targetColumn = ['PREVIEW_ATTACH', 'SEAL_WIDTH', 'SEAL_HEIGHT','ATTACH'];
if(id == 'S'){
	isHidden = false;
} else {
	isHidden = true;
}

for(var i in targetColumn){
	var idx = gridObj.getColIndexById(targetColumn[i]);
	gridObj.setColumnHidden(idx, isHidden);
}


        	var allowFileAttachType = ['IMAGE', 'SEAL'];
        	var itemType = this._getRowData(id).ITEM_TYPE;
        	var header = this.getColumnId(ind);
	        let item_code = this._getRowData(id).ITEM_CODE;

        	if(header == 'ATTACH' || header == 'PREVIEW_ATTACH') {
	        	if(itemType == ''){
        			Alert("항목타입을 선택해주세요.");
        			return;
	        	}else if(item_code == "U" || item_code =="C" || item_code=="E"){
        			return ;
        		}

	        	if(allowFileAttachType.indexOf(itemType) >= 0) {
        			var rowObj = gridObj._getRowData(id);

	        		if(itemType == 'SEAL') {
		        		if(header == 'ATTACH') {
		        			rowObj.LAYER = "SEAL_IMAGE";
		        		} else {
		        			rowObj.LAYER = "SEAL_PRE";
		        		}

		        		openFileExplorer(rowObj);
	        		} else if(itemType == 'IMAGE') {
	        			rowObj.ATTACH_TYPE = 'STD';
	        			attachImageFile(rowObj);
	        		}


	        	} else {
	        		Alert("항목타입이 '직인' 인 경우에만 파일첨부가 가능합니다.");
	        	}
			}


            var header = gridObj.getColumnId(cInd);
            let item_code = this._getRowData(rId).ITEM_CODE;

			if(stage == 0 && (header =='DISPLAY_TEMPLATE' || header == 'DISPLAY_EDIT')) {
                if(item_code == "U" || item_code =="C" || item_code=="E"){
        			return false;
        		}
            }else if(stage == 2 ) {
				if(header == 'SEAL_WIDTH' ) {
					var width = gridObj.cells(rId, gridObj.getColIndexById("SEAL_WIDTH")).getValue();
					var chkNumber = /^[0-9]+$/ ;
					if(!chkNumber.test(width)) {
						Alert(Sepoa.cache.text.get('MESSAGE.1094'));
						gridObj.cells(rId, gridObj.getColIndexById("SEAL_WIDTH")).setValue(oValue);
					} else if(width < 1) {
						Alert(Sepoa.cache.text.get('MESSAGE.1094'));
						gridObj.cells(rId, gridObj.getColIndexById("SEAL_WIDTH")).setValue(oValue);
					}
				}else if( header == 'SEAL_HEIGHT') {
					var height = gridObj.cells(rId, gridObj.getColIndexById("SEAL_HEIGHT")).getValue();
					var chkNumber = /^[0-9]+$/ ;
					if(!chkNumber.test(height)) {
						Alert(Sepoa.cache.text.get('MESSAGE.1094'));
						gridObj.cells(rId, gridObj.getColIndexById("SEAL_HEIGHT")).setValue(oValue);
					} else if(height < 1) {
						Alert(Sepoa.cache.text.get('MESSAGE.1094'));
						gridObj.cells(rId, gridObj.getColIndexById("SEAL_WIDTH")).setValue(oValue);
					}
				}
			}
            return true;


	var tmpImageFile = document.createElement('input');
    tmpImageFile.type = 'file';
    tmpImageFile.id = 'upload_file';
    tmpImageFile.name = 'upload_file';
    tmpImageFile.onchange = function(e) {
    	var files = e.currentTarget.files;
    	doImageFileUpload(rowObj, files);
    }

    tmpImageFile.click();


	var tmpFileInput = document.createElement('input');
    tmpFileInput.type = 'file';
    tmpFileInput.id = 'upload_file';
    tmpFileInput.name = 'upload_file';

    tmpFileInput.onchange = function(fe) {
        var files = fe.currentTarget.files;
        doFileUpload(rowObj, files);
    }

    tmpFileInput.click();


        	 var config = {
                multiple: false,
                url: window.CONTEXT_NAME + '/SepoaActionController.sux',
                ext: ['jpeg', 'jpg', 'png'],
                on: {
                    callback: function(res) {
                        if (res.status == "1") {
                        	if(rowObj.LAYER == "SEAL_IMAGE"){
				                gridObj.cells(rowObj.gr_id, gridObj.getColIndexById('ATTACH')).setIcon('ATTACH_IMG2');
				                gridObj.cells(rowObj.gr_id, gridObj.getColIndexById('ATTACH')).cell.children[0].style = 'filter:none';                        	
                        	}else {
                        		gridObj.cells(rowObj.gr_id, gridObj.getColIndexById('PREVIEW_ATTACH')).setIcon('ATTACH_IMG2');
				                gridObj.cells(rowObj.gr_id, gridObj.getColIndexById('PREVIEW_ATTACH')).cell.children[0].style = 'filter:none';
                        	}
                        	Alert(sUtils.cache.text.get('MESSAGE.0001'));
                        } else {
                        	console.log(res);
                            Alert(res.message);
                            formObj.uncheckItem('SEAL_IMG_FLAG');
                        }
                    }
                }
            }

            var params = {
                module: "seal.management",
                action: "doUploadSettingSealImage",
                CONNECTION: "TRANSACTION",
                MANAGE_DOC_NO : rowObj.ITEM_NO,
                FM_LAYER : rowObj.LAYER,
                files: files
            }

            sUtils.multipart.upload(config, params);


	 var config = {
        multiple: false,
        url: window.CONTEXT_NAME + '/SepoaActionController.sux',
        ext: ['jpeg', 'jpg', 'png'],
        on: {
            callback: function(res) {
                if (res.status == "1") {
                	if(res.result[0]) {
                		gridObj.cells(rowObj.gr_id, gridObj.getColIndexById('ATTACH_TYPE')).setValue(res.result[0].ATTACH_TYPE);
                		gridObj.cells(rowObj.gr_id, gridObj.getColIndexById('DES_FILE_PATH')).setValue(res.result[0].DES_FILE_PATH);
                	}
                	Alert(sUtils.cache.text.get('MESSAGE.0001'));
                } else {
                	console.log(res);
                    Alert(res.message);
                }
            }
        }
    }

    var params = {
        module: "sepoa.svc.contract.SepoaContractItem",
        action: "doUploadImageFile",
        CONNECTION: "TRANSACTION",
        ITEM_NO : rowObj.ITEM_NO,
        files: files
    }

    sUtils.multipart.upload(config, params);
